import warnings
from contextlib import suppress

from taf.config.testline.info import info
from taf.config.testline.info.exceptions import UserNotDefinedForSWLine
from taf.internal.aliasing import (
    AliasLookupError,
    LookupHandler,
    SeparateDefaultAliasStore,
)
from yaml import SafeLoader, load

from .clients import ClientInterface, client_builder
from .exceptions import AliasInUse

tl_info = info()


class rmod_serial_interface:
    """
    taf.hw.rmod_serial_interface is a library provides API for interacting with RMODs via either LMI or MUMIN boards.
    It allows user to remotely execute commands on RMODs, track serial communication, and secure logs even when a
    standard connection cannot be established (for example when FID 10 is visible on RMOD).

    Typical usage (Python):

        >>> from taf.hw.rmod_serial_interface import rmod_serial_interface   # import library
        >>> _rsi = rmod_serial_interface()    # initialize library
        >>> _rsi.setup_host('10.44.1.1', 'nokiauser', 'nokiapassword', port='9092', remote_dir='C:/rsi',
        >>>                 alias='my_host')   # setup connection to remote host if
        >>> _rsi.setup_rmod_connection('AHFII', 'COM15', alias='MRBTS-50001-AHFII-1',
                                       host_connection='my_host')   # setup connection to particular RMOD
        >>> output = _rsi.execute_command('df', alias='MRBTS-50001-AHFII-1')   # execute custom commands
        output = "Filesystem           1K-blocks      Used Available Use% Mounted on
        devtmpfs                778748         0    778748   0% /dev
        tmpfs                   860208     32764    827444   4% /dev/shm
        tmpfs                   860208    187848    672360  22% /run
        tmpfs                   860208         0    860208   0% /sys/fs/cgroup
        tmpfs                   860208      1092    859116   0% /tmp
        tmpfs                   860208      5116    855092   1% /var/volatile
        /dev/mtdblock20          26868         5     24570   0% /frozenframe
        /dev/mtdblock19          58085     44693      8806  84% /var/volatile/log
        ubi0:slot0_sw           233728    149504     79388  65% /mnt/slot0_sw
        ubi0:slot0_sw           233728    149504     79388  65% /mnt/slot_running
        ubi2:factory             14392        56     13564   0% /mnt/factory
        ubi3:runtime             25744     11016     13356  45% /mnt/runtime
        ubi1:slot1_sw           233728    186140     42752  81% /mnt/slot1_sw
        tmpfs                   262144         0    262144   0% /tmp/coredumps
        tmpfs                   172040         0    172040   0% /run/user/1002
        "
        >>> _rsi.download_log('/tmp/console_log.txt', alias='MRBTS-50001-AHFII-1')   # download console log
        >>> _rsi.teardown(alias='MRBTS-50001-AHFII-1')   # teardown connection to RMOD


    For more examples (including Robot Framework usage example) look into the examples directory
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    lookup_handler = LookupHandler(lookup_arg="host_connection", lookup_type=ClientInterface)
    _client_store = SeparateDefaultAliasStore(name=__name__)
    lookup_handler.store = _client_store

    def __init__(self):
        self._client_store.add(client_builder(client_type="local"))
        self._rmod_to_client_map = {}

    def setup_host(
        self,
        host,
        user,
        password,
        alias,
        port="9092",
        remote_dir="C:/rsi",
        python_path="python",
        upload=True,
        *,
        ssh_port=22,
        pyro_ip=None,
    ):
        """
        Sets up resources needed to maintain client-server communication with external host machine that has physical
        connections to RMODs. Stores alias for created client object to be used with interface keywords.

        :param str host:  ip address of host machine
        :param str user:  username on host machine
        :param str password:  password for specified user on this host
        :param str alias: connection alias to be stored for future referencing.
        :param str port:  port on which Pyro4 server will listen for connections. Defaults to 9092
        :param str remote_dir:  directory on host machine to which all server files will be copied.
                                Defaults to 'C:/rsi'
        :param str python_path:  path to python executable on host machine which will be used to run server.
                                 Defaults to 'python'.
        :param bool upload:  Specifies whether to upload server files to host before attempting
                             connection. Required when running for the first time (when server
                             files are not yet on host machine) or if we want to automatically
                             upload newer version. Disable to save some time. Defaults to True
        :param int ssh_port:  port on which SSH is enabled on host. Defaults to 22
        :param str pyro_ip:  Specifies IP address to which Pyro server instance will be bound. In most cases this
                             parameter can be left with default 'None' value, which bounds server instance to the
                             same IP as host. Make sure that passed IP address is reachable from test machine.
        :return PyroClient: Client object representing created connection to host
        """
        self._check_host_alias_in_use(alias)
        new_host = client_builder(
            "PYRO", host, user, password, ssh_port, pyro_ip, port, remote_dir, python_path, upload
        )
        self._client_store.add(new_host, alias)
        return new_host

    @lookup_handler.implicit_lookup
    def setup_rmod_connection(self, rmod_type, port, alias=None, host_connection=None, fh_interface=None):
        """
        Sets up connection to concrete RMOD. After connection is established all communication on RMOD's serial port
        is being logged. Creates directory on RMODs NV-RAM for snapshots to be stored, or cleans remaining logs if such
        directory already exists.

        :param str rmod_type: type of radio unit to establish connection to. Required for extracting login/password
                              from database for a given RMOD type
        :param str port: Specifies port on which RMOD is connected to its host. It can be either Serial port or Telnet
                         pair of <ip:port>, i.e '10.42.11.11:1000'. Serial port on Windows hosts will usually be
                         'COMx' while on UNIX hosts it will usually be '/dev/ttySx' where 'x' stands for port number,
                         i.e: COM13 or /dev/ttyS13

        :param str alias: Specifies alias which will reference connection to this RMOD in other keywords. If left as
                          None, it will try to read serial number from connected RMOD and set it as alias.

        :param str/ClientInterface connection: alias of host on which selected RMOD is connected (as specified in
                                               setup_host kw) or ClientInterface object returned from ``setup_host``
                                               kw. If left as None, it is assumed that RMOD is connected to/accessible
                                               from localhost (VM/PC which test runs on) - no proxy host needed.
        :param str fh_interface: Specifies which RMOD version to use as sometimes the same RMOD type comes with
                                 different software line depending on utilized fronthaul interface. Possible values
                                 include CPRI and eCPRI. Defaults to None.
        :returns: str - alias referencing established connection.
        """

        self._check_rmod_alias_in_use(alias)
        login, password = self._get_ru_credentials(rmod_type, fh_interface)
        sn = host_connection.setup_rmod_connection(login, password, port)
        if alias is None:
            self._check_rmod_alias_in_use(sn)
            alias = sn
        self._rmod_to_client_map[alias] = {"port": port, "sn": sn, "host_connection": host_connection}
        return alias

    @lookup_handler.implicit_lookup
    def setup_custom_rmod_connection(
        self, port, login, password, shell_prompt_regex=None, alias=None, host_connection=None
    ):
        """
        Sets up custom connection to concrete RMOD using provided credentials. Use this method if
        ``setup_rmod_connection`` with your rmod_type results in RUNotSupported error. After connection is
        established all communication on RMOD's serial port is being logged. Creates directory on RMODs NV-RAM
        for snapshots to be stored, or cleans remaining logs if such directory already exists.

        :param str port: please refer to ``setup_rmod_connection`` keyword
        :param str login: RMODs account username i.e. rfsw, serviceuser, root
        :param str password: RMODs account password
        :param str shell_prompt_regex: Regex that correctly matches RMODs shell prompt. If left as None,
                                       default regex is used that works in majority cases. Having improper
                                       shell_prompt_regex leads to various login errors.
        :param str alias: please refer to ``setup_rmod_connection`` keyword
        :param str/ClientInterface connection: please refer to ``setup_rmod_connection`` keyword
        :returns: str - connected RMOD's serial number
        """

        self._check_rmod_alias_in_use(alias)
        sn = host_connection.setup_custom_rmod_connection(port, login, password, shell_prompt_regex)
        if alias is None:
            alias = sn
        self._rmod_to_client_map[alias] = {"port": port, "sn": sn, "host_connection": host_connection}
        return alias

    def setup_rmod_connection_from_ru_config(
        self, ru_config, alias=None, host_alias=None, fh_interface=None, use_init_credentials=False, **kwargs
    ):
        """
        Sets up connection to concrete RMOD using provided taf.config.testline.RU object. After connection is
        established all communication on RMOD's serial port is being logged. Creates directory on RMODs NV-RAM
        for snapshots to be stored, or cleans remaining logs if such directory already exists. Sets up 2 seperate
        connections if RMODs has 2 UARTs configured in ru_config object. If provided rmod_type is not recognized
        as oficially supported, connection is setup as custom with login/password taken from ssh_details in ru_config.
        Returns tuple (str, str) holding aliases to main connection and optional alias of RMOD's second UART connection

        :param taf.config.testline.RU ru_config: TAF configuration object holding all necessary information,
                                                 specifically rmod_type, lmp_connection and ssh_details
        :param str alias: (Optional) please refer to ``setup_rmod_connection`` keyword
        :param str host_alias: (Optional) alias to be assigned to host connection if such connection is configured in
                               ru_config. By default alias is set to host connection address value.
        :param str fh_interface: (Optional) please refer to ``setup_rmod_connection`` keyword
        :param bool use_init_credentials: (Optional) whether to use custom credentials from ru_config or
            default credentials from database
        :param dict **kwargs: (Optional) - Additional arguments passed to ``setup_host`` keyword if such proxy is
                                           required for rmod connection
        :returns: (str, str/None) - 2 element tuple holding: (main_connection alias, second_uart_connection_alias)

        """
        lmi, radio_type, ssh_creds = self._extract_crucial_data_from_ru_config(ru_config)
        host = self._setup_host_from_ru_config(lmi, host_alias, **kwargs)
        aliases = []
        for idx, uart in enumerate(lmi.uart_mapping):
            port = self._extract_board_connection_port(uart)
            new_alias = alias if idx == 0 or alias is None else f"{alias}_{idx + 1}"
            aliases.append(
                self._setup_rmod_connection_from_ru_config(
                    port,
                    radio_type,
                    ssh_creds,
                    new_alias,
                    host_connection=host,
                    fh_interface=fh_interface,
                    use_init_credentials=use_init_credentials,
                )
            )
        return aliases

    @staticmethod
    def _get_ru_credentials(rmod_type, fh_interface):
        default_creds = ("root", "")
        try:
            sw_line = tl_info.get_ru_sw_line(radio_type=rmod_type, fh_interface=fh_interface)
            if not sw_line:
                return default_creds
            password = tl_info.get_ru_password(by_sw_line=sw_line)
        except UserNotDefinedForSWLine:
            return default_creds
        return "serviceuser", password

    @staticmethod
    def _extract_crucial_data_from_ru_config(ru_config):
        lmi = ru_config.lmi
        radio_type = ru_config.radio_type
        ssh_creds = rmod_serial_interface._get_ssh_credentials_from_ru_config(ru_config)
        if lmi is None:
            raise AttributeError("Provided RU does not have lmi object")
        if radio_type is None:
            radio_type = "default"
        return lmi, radio_type, ssh_creds

    def _setup_host_from_ru_config(self, lmi, alias, **kwargs):
        try:
            ssh_details = lmi.host.default_ssh_connection_details
            addr = ssh_details.addr
            username = ssh_details.username
            password = ssh_details.password
            ssh_port = kwargs.pop("ssh_port", None)
            ssh_port = ssh_details.port if ssh_port is None else ssh_port
            alias = addr if alias is None else alias
            return self.setup_host(addr, username, password, alias=alias, ssh_port=ssh_port, **kwargs)
        except AttributeError:
            pass
        except AliasInUse:
            return addr

    @staticmethod
    def _extract_board_connection_port(uart):
        port = uart.port
        try:
            addr = uart.addr
            if hasattr(addr, "v4"):
                addr = addr.v4
            port = f"{addr}:{port}"
        except AttributeError:
            pass
        return port

    def _setup_rmod_connection_from_ru_config(
        self, port, rmod_type, ssh_creds, alias, host_connection, fh_interface, use_init_credentials=False
    ):
        if use_init_credentials:
            if ssh_creds:
                login, password = ssh_creds
                alias = self.setup_custom_rmod_connection(
                    port, login, password, alias=alias, host_connection=host_connection
                )
            else:
                raise AttributeError("No default_ssh_connection_details for this RU has been provided")
        else:
            alias = self.setup_rmod_connection(rmod_type, port, alias, host_connection, fh_interface=fh_interface)
        return alias

    @staticmethod
    def _get_ssh_credentials_from_ru_config(ru_config):
        ssh_details = ru_config.default_ssh_connection_details
        if ssh_details is None:
            return None
        login = ssh_details.username
        if isinstance(login, dict):
            login = list(login.values())[-1]
        password = ssh_details.password
        if isinstance(password, dict):
            password = list(password.values())[-1]
        return login, password

    def load_config(self, config):
        """
        Loads configuration from either dict or yaml file and sets up all connections accordingly. Can be used instead
        of multiple calls of ``setup_host`` and ``setup_rmod_connection`` keywords

        Configuration dict structure:
            >>> config = {
            >>>     'localhost': {
            >>>         'RMODs': {
            >>>             # Each RMOD here means separate call to setup_rmod_connection for localhost which means
            >>>             # that those RMODs must be directly accessible from host that this code runs on
            >>>             '10.0.0.1:1000': 'AHFII',
            >>>             '10.1.1.1:1005': 'AHLOA'
            >>>         }
            >>>     }
            >>>     # Each alias other than 'localhost' here means separate call to setup_host - refer to
            >>>     # setup_host kw documentation for params
            >>>     'external_host_alias_1': {
            >>>         # following are arguments passed to client of specified type during host setup
            >>>         'host': '10.44.1.1',
            >>>         'user': 'nokiauser',
            >>>         'password': 'strong_pass!1',
            >>>         'port': '9002',
            >>>         'remote_dir': 'C:/rsi',
            >>>         'python_path': 'python',
            >>>         'RMODs': {
            >>>             # Each RMOD here means separate call to setup_rmod_connection for current host alias
            >>>             'COM14': 'AHFII',
            >>>             'COM15': 'AHLOA'
            >>>         }
            >>>     },
            >>>     'external_host_alias_2': {
            >>>         'host': '10.44.100.100',
            >>>         'user': 'ute',
            >>>         'password': 'stronger_pass@2',
            >>>         'port': '9002',
            >>>         'remote_dir': '/home/ute/rsi',
            >>>         'python_path': '/home/ute/venv/bin/python',
            >>>         'RMODs': {
            >>>             '/dev/ttyS3': 'AZHL',
            >>>             '/dev/ttyS4': 'AHFIG'
            >>>         }
            >>>     }
            >>> }

        If config parameter is a string instance it will be interpreted as path to .yaml file with similar structure,
        the only difference being that the whole config section must be wrapped at the top level as 'RSI' key, e.g:
            ``
            RSI:
                LOCALHOST:
                    RMODs:
                        10.0.0.1:1000: 'AHFII'
                        10.1.1.1:1005: 'AHLOA'
                # Each alias here means separate call to setup_host
                HOST_ALIAS_1:
                    # following are arguments passed to client of specified type during host setup
                    host: '10.44.1.1'
                    user: 'nokiauser'
                    password: 'strong_pass!1'
                    port: '9002'
                    remote_dir: 'C:/rsi'
                    python_path: 'python'
                    RMODs:
                        # Each RMOD here means separate call to setup_rmod_connection for this host alias
                        COM14: 'AHFII'
                        COM15: 'AHLOA'
            ``

        :returns: dict containing loaded RMOD's serial numbers with following structure: {'host_alias_1': {'port': sn}}
        """

        config = self._resolve_config_type(config)
        loaded_info = {}
        try:
            for host_alias, host_params in config.items():
                if not host_params:
                    raise ValueError(f"Host alias ({host_alias}) does not have any parameters defined in config")
                host_alias, host_params, rmods = self._parse_host_data(host_alias, host_params)
                loaded_info[host_alias] = {}
                for port, rmod_type in rmods.items():
                    alias = self.setup_rmod_connection(rmod_type=rmod_type, port=port, host_connection=host_alias)
                    loaded_info[host_alias][port] = alias
        except Exception:
            self._teardown_connections_made_up_to_this_point(loaded_info)
            raise
        return loaded_info

    @staticmethod
    def _resolve_config_type(config):
        if isinstance(config, str):
            with open(config, "r") as f:
                config = load(f, Loader=SafeLoader).get("RSI", {})
        return config

    def _parse_host_data(self, host_alias, host_params):
        rmods = host_params.pop("RMODs", {})
        rmods = rmods if rmods is not None else {}
        if host_params.pop("type", ""):
            warnings.warn(
                message="parameter 'type' in host config is deprecated and can be safely removed "
                "from config. It will be completely removed in future versions",
                category=DeprecationWarning,
            )
        if host_alias.lower() != "localhost":
            with suppress(AliasInUse):
                self.setup_host(alias=host_alias, **host_params)
        else:
            host_alias = None
        return host_alias, host_params, rmods

    def _teardown_connections_made_up_to_this_point(self, loaded_info):
        aliases = [alias for rmods in loaded_info.values() for alias in rmods.values()]
        for alias in aliases:
            self.teardown(alias)

    def send_command(self, cmd, alias, elevated=False, wait_echo=True):
        """
        Executes command on RMOD and returns immediately (non-blocking)

        :param str cmd: command to be executed
        :param str alias: alias of RMOD connection
        :param bool elevated: try to run command with elevated permissions.
        :param bool wait_echo: if True, send with echo-based ack (slower, more reliable); if False,
            send without waiting for echo.
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        host_connection.send_command(cmd, port, elevated, wait_echo)

    def execute_command(self, cmd, alias, elevated=False, timeout=30, wait_echo=True):
        """
        Executes command on RMOD and waits for output or timeout (blocking). Output is considered collected when
        shell prompt is reached.

        :param str cmd: command to be executed
        :param str alias: alias of RMOD connection
        :param bool elevated: try to run command with elevated permissions.
        :param float timeout: maximum time to wait for an output.
        :param bool wait_echo: if True, send with echo-based ack (slower, more reliable); if False,
            send without waiting for echo.
        :returns: str - command's output

        WARNING: Output can be contaminated by anything that RMOD decides to expose on serial port like boot messages
                 or even output of commands that have been ran in the background either manually or with
                 ``send_command`` kw
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        return host_connection.execute_command(cmd, port, elevated, timeout, wait_echo)

    def take_snapshot(self, alias, timeout=180):
        """
        Initiates MUMIN procedure of securing RMOD's snapshot (also called Paszczak's Gambit). Snapshot is initially
        collected on RMOD's /ram and it is later moved to the /rom memory. Keep in mind that it is not downloaded from
        RMOD, but is only secured in RMOD's non-volatile memory for user to fetch it later. Keep also in mind that
        this process is very error prone as usually we want to secure this snapshot when RMOD's shows alarms/failure
        symptoms and is generally quite unstable. It may also happen that /rom memory is too small to contain whole
        snapshot. Hence, we do not guarantee that snapshot will be collected successfully, but usually it is still
        worth attempting. Path to secured snapshot on RMOD is returned from this keyword if collected without errors.

        :param str alias: alias of RMOD connection
        :param float timeout: maximum time to wait for snapshot generation
        :returns: str - path to generated snapshot on RMOD
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        return host_connection.take_snapshot(port, timeout)

    def collect_rmod_output(self, alias):
        """
        Returns RMODs console output excluding output already collected by using this keyword or ``execute_command``

        :param str alias: alias of RMOD connection
        :returns: str - console output
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        return host_connection.collect_rmod_output(port)

    def teardown(self, alias):
        """
        Teardown connection to RMOD.  Refer to ``shutdown`` keyword if you need
        to close all connections on host AND kill the server.

        :param str alias: alias of RMOD connection
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        host_connection.teardown(port)
        del self._rmod_to_client_map[alias]

    @lookup_handler.implicit_lookup
    def teardown_all_rmods_on_host(self, host_connection=None):
        host_connection.teardown()
        self._remove_rmods_with_torndown_host()

    def teardown_all_hosts(self):
        stored = list(self._client_store.all)
        for alias, client in stored:
            self.teardown_all_rmods_on_host(client)

    def shutdown(self, host_connection=None):
        """
        Shuts down server running on host machine. Use very carefully! It will shutdown the server for other users
        who might be using it to collect logs from other RMODs. We advice sticking only to 'teardown' keyword and leave
        the server running. It may be closed manually later when no harm is assured.

        :param str/ClientInterface connection: please refer to ``setup_rmod_connection`` keyword. In this particular
                                               case, if value is left as None it shuts down all aliases including
                                               connection made to 'localhost'
        """

        if host_connection is not None:
            self._shutdown_alias(host_connection)
        else:
            stored = list(self._client_store.all)
            for alias, client in stored:
                client.shutdown()
                self._client_store.remove(alias)
            self._client_store.get().shutdown()
        self._remove_rmods_with_torndown_host()

    @lookup_handler.implicit_lookup
    def _shutdown_alias(self, host_connection=None):
        host_connection.shutdown()
        self._client_store.remove_object(host_connection)

    def download_log(self, local_path, alias):
        """
        Download serial communication log for specified RMOD on given host. This keyword does not reset the log nor
        stops the logging itself; Log is still building up in the background while user downloads only current state of
        the log. This means user can call this keyword several times and review changes to the log.

        :param str local_path: path to which log will be saved on local machine.
        :param str alias: alias of RMOD connection
        :returns: local path (str) is being returned for coherence
        """

        port, _, host_connection = self._get_rmod_connection(alias).values()
        return host_connection.download_log(local_path, port)

    def _check_host_alias_in_use(self, alias):
        for stored_alias, _ in self._client_store.all:
            if stored_alias == alias:
                raise AliasInUse(alias)

    def _check_rmod_alias_in_use(self, alias):
        if alias in self._rmod_to_client_map:
            raise AliasInUse(alias)

    def _get_rmod_connection(self, alias):
        if alias not in self._rmod_to_client_map:
            raise AliasLookupError(f"alias {alias} does not exist")
        return self._rmod_to_client_map[alias]

    def _remove_rmods_with_torndown_host(self):
        aliases_to_remove = []
        for alias, data in self._rmod_to_client_map.items():
            if data["host_connection"].torndown:
                aliases_to_remove.append(alias)
        for alias in aliases_to_remove:
            del self._rmod_to_client_map[alias]

    @staticmethod
    def get_rmod_credentials(rmod_type, fh_interface=None):
        """
        Returns login and password for specific RMOD.

        .. deprecated:: 2.5.0
            This function is deprecated and should no longer be used to retrieve RMOD credentials.
            Use ``get_ru_password`` and ``get_ru_sw_line`` from ``taf.config.testline.info`` instead.
            This function will be removed in future versions.

        :param str rmod_type: type of radio unit to establish connection to.
        :return: tuple - A tuple containing:
             - str: login
             - str: password
        """
        warnings.warn(
            message="get_rmod_credentials is deprecated and should no longer be used to retrieve RMOD credentials. "
            "Use 'get_ru_password' and 'get_ru_sw_line' from 'taf.config.testline.info' instead. "
            "This function will be removed in future versions.",
            category=DeprecationWarning,
            stacklevel=2,
        )
        return rmod_serial_interface._get_ru_credentials(rmod_type, fh_interface)

    def get_rmod_info(self, alias):
        """
        Returns the status information of a given RMOD.

        :param str alias: alias of RMOD connection
        :return: dict - A dictionary containing:
              - connected (bool): True if the communication with radio serial interface is established, False otherwise.
              - logged_in (bool): True if the radio serial interface (rsi) is logged in, False otherwise.
              - uboot_detected (bool): True if the radio is in U-Boot mode, False otherwise.
              - login_possible (bool): True if the radio is ready for login, False otherwise.
        """
        port, _, host_connection = self._get_rmod_connection(alias).values()
        return host_connection.get_rmod_info(port)

    def get_rmod_serial_number(self, alias):
        """
        Returns serial_number that has been read from RMOD during connection setup. Slave node connections
        will return internal connection id with following form: {hostname}-id-{datetime}.

        :param str alias: alias of RMOD connection
        :return: str - RMODs serial_number or internal connection ID
        """
        return self._get_rmod_connection(alias)["sn"]

    def set_rmod_credentials(self, login, password, alias, shell_prompt_regex=None):
        """
        Sets login credentials and optionally shell prompt regex for an existing RMOD connection.
        This allows updating credentials for a connection that was previously set up, replacing
        credentials that were only looked up from the database during initial connection setup.

        :param str login: RMOD account username (e.g., rfsw, serviceuser, root)
        :param str password: RMOD account password
        :param str alias: alias of RMOD connection
        :param str shell_prompt_regex: Optional regex that correctly matches RMOD's shell prompt.
                                       If left as None, the default regex is used.
        """
        port, _, host_connection = self._get_rmod_connection(alias).values()
        host_connection.set_rmod_credentials(port, login, password, shell_prompt_regex)
